// Intended function: allocate local utility supply to demand through explicit compatible links in stable order with capacity/loss accounting.
#include "world/UtilityNetwork.hpp"
#include <algorithm>
namespace elysium{void UtilityNetwork::upsertPort(UtilityPort p){ports_[p.portId]=p;}void UtilityNetwork::upsertLink(UtilityLink l){links_[l.linkId]=l;}std::vector<UtilityAllocation>UtilityNetwork::solve(UtilityKind k,std::size_t max)const{std::vector<UtilityPort>src,sink;for(auto&[_,p]:ports_)if(p.enabled&&p.kind==k){if(p.supply>0)src.push_back(p);if(p.demand>0)sink.push_back(p);}std::sort(src.begin(),src.end(),[](auto&a,auto&b){return a.portId<b.portId;});std::sort(sink.begin(),sink.end(),[](auto&a,auto&b){return a.portId<b.portId;});std::vector<UtilityAllocation>o;for(auto&s:src){float avail=std::min(s.supply,s.capacity);for(auto&d:sink){if(o.size()>=max||avail<=0)break;float linkCap=0,loss=0;for(auto&[_,l]:links_)if(l.enabled&&l.kind==k&&((l.a==s.portId&&l.b==d.portId)||(l.b==s.portId&&l.a==d.portId))){linkCap+=l.capacity;loss=std::max(loss,l.lossPerUnit);}if(linkCap<=0)continue;float q=std::min({avail,d.demand,linkCap});float lost=q*std::clamp(loss,0.f,.95f);o.push_back({s.portId,d.portId,k,q-lost,lost});avail-=q;d.demand-=q;}}return o;}}
